        public bool errors = false;
        public string message = "";
        public string firstName = "";
        public string lastName = "";
        public string address = "";
        public string phone = "";
        public string inquiry = "";

        public bool badCharCheck(string toCheck)
        {
            var badChars = new [] { "@", "#", "$", "\"", "%" }; // chars not allowed in names
            var passed = false;

            foreach (var letter in toCheck)
            {
                if (Array.Exists(badChars, x => x == letter.ToString())) // checks each character against those in the array (not as nice looking as python)
                {
                    passed = false;
                    break;
                }
                else
                {
                    passed = true;
                }
            }

            return passed;
        }

        public void OnPost()
        {
            firstName = Request.Form["first_name"].ToString().Trim();
            lastName = Request.Form["last_name"].ToString().Trim();
            address = Request.Form["address"].ToString().Trim();
            phone = Request.Form["phone"].ToString().Trim();
            inquiry = Request.Form["inquiry"].ToString().Trim();

            message += validateName("first name", firstName, new int[] { 3, 10 });
            message += validateName("last name", lastName, new int[] { 2, 15 });
            message += validateAddress(address);
            message += validatePhone(phone);
            message += validateInquiry(inquiry);

            if (message != "")
                message = "<div class=\"alert alert-danger\" role=\"alert\">" + message + "</div>";
            else
                message = "<div class=\"alert alert-success\" role=\"alert\">The form has been submitted successfully!</div>";
        }

        public string validateAddress(string data)
        {
            if (data != "" && (data.Length < 8 || data.Length > 25))
                return "Your address must be between 8 and 25 characters long.<br>";
            else
                return "";
        }

        public string validateInquiry(string data)
        {
            if (data == "")
                return "You must enter an inquiry.";
            else
                return "";
        }

        public string validateName(string field, string data, int[] length)
        {
            var errorMessage = "";

            if (data == "")
                return "You must enter your " + field + ".<br>";
            if (data.Length < length[0] || data.Length > length[1]) // make sure the data entered is within the length range
                errorMessage += "Your " + field + " must be between " + length[0] + " and " + length[1] + " characters long.<br>";
            if (!badCharCheck(data))
                errorMessage += "Your " + field + " contains invalid characters.<br>";

            return errorMessage;
        }

        public string validatePhone(string data)
        {
            var errorMessage = "";
            var length = 10;

            if (data.Contains("-"))
                length = 12;
            if (data == "")
                errorMessage = "You must enter a phone number.<br>";
            else if (data.Length != length)
                errorMessage = "Your phone number must be " + length + " characters long.<br>";

            return errorMessage;
        }
    

